package sohal.lld.battleship.ship;import sohal.lld.battleship.model.Coord;import java.util.HashSet;import java.util.Set;public class ShipFactory {    /**     * Create a square ship with given center (cx,cy) and integer side length 'size'.     * The definition matches the spec: size=4 centered at (2,2) -> covers x in [0..4].     */    public static SquareShip createSquareShip(String id, int size, int cx, int cy) {        if (size <= 0) throw new IllegalArgumentException("size must be > 0");        int half = size / 2;        int xStart = cx - half;        int xEnd = cx + half;        int yStart = cy - half;        int yEnd = cy + half;        Set<Coord> cells = new HashSet<>();        for (int x = xStart; x <= xEnd; x++) {            for (int y = yStart; y <= yEnd; y++) {                cells.add(new Coord(x, y));            }        }        return new SquareShip(id, size, cells);    }}